// ATOM2_W10 (trecho de n8n/code/w10_proposta.js)
// ATOM2_W10 · Proposta (Fluxo do Funil v1.0 §5; scripts "Acompanhamento/Encerramento da proposta", "Cliente aceitou").
// ÚNICO ponto onde preço aparece: o Thiago informa serviço, escopo, valor, condições e prazo no painel (nunca inventamos números).
// Cada envio cria uma versão nova (P-<deal>-v<n>) com página privada (token, noindex, validade). Ao registrar:
//   Pipedrive → etapa Proposta, valor do negócio, "ATOM · Link da proposta" (= proposta enviada: libera preço no W08), proposal_id;
//   empresa → F9; rascunho da mensagem de envio para o Thiago mandar (não sai sozinho).
// Aceite pela página (botão com confirmação) → proposta aceita, negócio GANHO (= aceite, F11) → pós-venda (contrato/cobrança).
const API = 'https://api.pipedrive.com/v1';
const SERVICOS = ['Site', 'Marketing com IA', 'Agente de IA', 'Clínica completa'];
