const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const brl = (v) => 'R$ ' + Number(v).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const dataBR = (iso) => { const d = String(iso || '').slice(0, 10).split('-'); return d.length === 3 ? d[2] + '/' + d[1] + '/' + d[0] : ''; };
function novoToken() {
  try { if (typeof crypto !== 'undefined' && crypto.getRandomValues) { const a = new Uint8Array(16); crypto.getRandomValues(a); return Array.from(a, (b) => b.toString(16).padStart(2, '0')).join(''); } } catch (e) { /* segue */ }
  let s = '';
  while (s.length < 32) s += Math.floor(Math.random() * 16).toString(16);
  return s;
}
const cfgMapa = (rows) => Object.fromEntries((rows || []).filter((r) => r && r.chave).map((r) => [r.chave, String(r.valor ?? '')]));
// Valor digitado no padrão brasileiro: "3.500,00", "3500", "3500.5".
function valorNum(v) {
  const s = String(v ?? '').replace(/[R$\s]/g, '');
  if (!s) return NaN;
  if (/,\d{1,2}$/.test(s)) return Number(s.replace(/\./g, '').replace(',', '.')); // 3.500,00
  if (/^\d{1,3}(\.\d{3})+$/.test(s)) return Number(s.replace(/\./g, ''));        // 12.000 (milhar, não decimal)
  return /^\d+$/.test(s) ? Number(s) : NaN;                                       // 3500; "3.50"/"3500.5" são ambíguos (use vírgula)
}
// Negócios que podem receber proposta: no Pipedrive, sem opt-out, já respondidos/qualificados (F6–F10) ou receptivos em atendimento.
function elegiveis(empresas, propostas) {
  return (empresas || []).filter((e) => e && e.pipedrive_deal_id && !(e.opt_out === true || String(e.opt_out) === 'true') && ['F6', 'F7', 'F8', 'F9', 'F10', 'IN_ATENDIMENTO', 'IN_QUALIFICADO', 'IN_REUNIAO', 'IN_PROPOSTA', 'IN_NEGOCIACAO'].includes(e.funil_etapa))
    .map((e) => ({ empresa: e, versoes: (propostas || []).filter((p) => p && String(p.deal_id) === String(e.pipedrive_deal_id)).length }));
}
function validar(b) {
  const erros = [];
  const valor = valorNum(b.valor);
  if (!SERVICOS.includes(b.servico)) erros.push('serviço inválido');
  if (!String(b.escopo || '').trim() || String(b.escopo).length > 4000) erros.push('escopo vazio ou longo demais');
  if (!(valor > 0) || valor > 1000000) erros.push('valor inválido');
  if (!String(b.condicoes || '').trim()) erros.push('informe as condições de pagamento');
  if (!String(b.prazo || '').trim()) erros.push('informe o prazo');
  const dias = Number(b.validade_dias || VALIDADE_DIAS_PADRAO);
  if (!(dias >= 1 && dias <= 90)) erros.push('validade entre 1 e 90 dias');
  return { ok: !erros.length, erros, valor, dias };
