</style></head><body><main>${corpo}</main>${extra || ''}</body></html>`;
}
// Painel do Thiago (protegido pelo QA_TOKEN).
function painel(k, empresas, propostas) {
  const lista = elegiveis(empresas, propostas);
  const opcoes = lista.map((x) => `<option value="${esc(x.empresa.pipedrive_deal_id)}">${esc(x.empresa.nome)} · negócio ${esc(x.empresa.pipedrive_deal_id)} · ${esc(x.empresa.funil_etapa)}${x.versoes ? ' · já tem ' + x.versoes + ' versão(ões)' : ''}</option>`).join('');
  const corpo = `<h1>Nova proposta</h1><p class="sub">Só aqui entra preço. Registrar move o negócio para Proposta, grava o link no Pipedrive e deixa a mensagem pronta numa nota (você envia).</p>
${lista.length ? `<form class="card" id="f"><label>Negócio<select name="deal_id" required>${opcoes}</select></label>
<label>Serviço<select name="servico" required>${SERVICOS.map((s) => `<option>${esc(s)}</option>`).join('')}</select></label>
<label>Escopo (o que está incluído)<textarea name="escopo" rows="6" required maxlength="4000"></textarea></label>
<label>Valor total (R$)<input name="valor" required inputmode="decimal" placeholder="ex.: 3.500,00"></label>
<label>Condições de pagamento<input name="condicoes" required maxlength="300" placeholder="ex.: 50% na assinatura e 50% na entrega"></label>
<label>Prazo de entrega<input name="prazo" required maxlength="120"></label>
<label>Validade (dias)<input name="validade_dias" type="number" min="1" max="90" value="${VALIDADE_DIAS_PADRAO}"></label>
<button type="submit">Registrar proposta</button><span class="status" role="status"></span></form>` : '<p class="card">Nenhum negócio elegível agora (precisa ter respondido e estar no Pipedrive).</p>'}`;
  const js = `<script>const K=${JSON.stringify(k)};const f=document.getElementById('f');if(f)f.addEventListener('submit',async(ev)=>{ev.preventDefault();const b=f.querySelector('button'),st=f.querySelector('.status');b.disabled=true;st.textContent='Salvando…';
try{const r=await fetch(location.pathname+'-salvar?k='+encodeURIComponent(K),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.erro||'erro '+r.status);st.innerHTML='Registrada: <a href="'+j.link+'" target="_blank" rel="noopener">'+j.proposal_id+'</a> ('+j.valor+')';}
catch(e){st.textContent='Não salvo: '+e.message;b.disabled=false;}});</script>`;
  return pagina('Nova proposta', corpo, js);
}
const tok = ($('Ler config (painel)').all().map((i) => i.json).find((r) => r && r.chave === 'QA_TOKEN') || {}).valor;
const k = String(($('Painel (GET)').first().json.query || {}).k || '');
const autorizado = !!tok && k === String(tok);
if (!autorizado) return [{ json: { status: 403, html: '<!doctype html><meta charset="utf-8"><title>Acesso negado</title><p>Acesso negado.</p>' } }];
return [{ json: { status: 200, html: painel(k, $('Ler empresas (painel)').all().map((i) => i.json), $('Ler propostas (painel)').all().map((i) => i.json)) } }];

