// Cria a versão da proposta e os planos. ctx: { empresas, propostas, cfgRows, agora, gerador }.
function criar(b, ctx) {
  const cfg = cfgMapa(ctx.cfgRows);
  const agora = ctx.agora || new Date().toISOString();
  const v = validar(b);
  if (!v.ok) return { ok: false, erro: v.erros.join('; ') };
  const alvo = elegiveis(ctx.empresas, ctx.propostas).find((x) => String(x.empresa.pipedrive_deal_id) === String(b.deal_id));
  if (!alvo) return { ok: false, erro: 'negócio não elegível para proposta' };
  const e = alvo.empresa;
  const versao = alvo.versoes + 1;
  const token = (ctx.gerador || novoToken)();
  const link = (cfg.PROPOSTA_BASE_URL || '') + '?t=' + token;
  if (!cfg.PROPOSTA_BASE_URL) return { ok: false, erro: 'PROPOSTA_BASE_URL ausente em atom2_config' };
  const proposta = { proposal_id: 'P-' + e.pipedrive_deal_id + '-v' + versao, company_id: e.company_id, deal_id: String(e.pipedrive_deal_id), versao, servico: b.servico, escopo: String(b.escopo).trim(), valor_total: Math.round(v.valor * 100) / 100, condicoes: String(b.condicoes).trim(), prazo: String(b.prazo).trim(), validade_ate: new Date(new Date(agora).getTime() + v.dias * 86400000).toISOString(), token, link, status: 'enviada', criado_em: agora, vistas: 0 };
