  if (cfg.PD_DEAL_VALOR_TOTAL_KEY) body[cfg.PD_DEAL_VALOR_TOTAL_KEY] = proposta.valor_total;
  if (cfg.PD2_FIELD_PROPOSTA_ID) body[cfg.PD2_FIELD_PROPOSTA_ID] = proposta.proposal_id;
  if (cfg.PD2_FIELD_PROXIMA_ACAO) body[cfg.PD2_FIELD_PROXIMA_ACAO] = 'Acompanhar a proposta ' + proposta.proposal_id;
