    pd: [
      { method: 'PUT', url: API + '/deals/' + e.pipedrive_deal_id, body },
      { method: 'POST', url: API + '/notes', body: { deal_id: Number(e.pipedrive_deal_id), pinned_to_deal_flag: 1, content: `<p><b>Proposta ${esc(proposta.proposal_id)}</b> · ${esc(proposta.servico)} · ${brl(proposta.valor_total)} · válida até ${dataBR(proposta.validade_ate)}</p><p>${esc(proposta.escopo).replace(/\n/g, '<br>')}</p><p>Condições: ${esc(proposta.condicoes)} · Prazo: ${esc(proposta.prazo)}</p><p>Link: <a href="${esc(link)}">${esc(link)}</a></p><p><b>Mensagem para enviar:</b><br>${esc(rascunho).replace(/\n/g, '<br>')}</p>` } }
