    evento: { event_id: 'e_w10_' + proposta.proposal_id + '_criada', correlation_id: 'deal_' + proposta.deal_id, company_id: e.company_id, workflow: 'ATOM2_W10', tipo: 'PROPOSTA_ENVIADA', motivo: proposta.servico, dados: JSON.stringify({ valor_total: proposta.valor_total, versao }), ocorrido_em: agora }
  };
