function registrosProposta(c, resps) {
  const r = (resps || [])[0] || {};
  if (r.success !== true) return [{ destino: 'evento', linha: { ...c.evento, event_id: c.evento.event_id + '_crm_falha', tipo: 'CRM_FALHA', motivo: 'Pipedrive recusou a proposta; nada foi gravado, tente de novo', dados: JSON.stringify({ erro: r.error || r.error_info || null }) } }];
  return [{ destino: 'proposta', linha: c.proposta }, { destino: 'empresa', linha: c.empresa }, { destino: 'cadencia', linha: c.cadencia }, { destino: 'mensagem', linha: c.mensagem }, { destino: 'evento', linha: c.evento }];
}
return registrosProposta($('Criar proposta').first().json, $('Aplicar no Pipedrive').all().map((i) => i.json)).map((j) => ({ json: j }));

