// Página da proposta para o cliente.
function paginaProposta(token, propostas, empresas, agoraISO, cfg) {
  const agora = agoraISO || new Date().toISOString();
  const nao = { status: 404, html: pagina('Proposta indisponível', '<h1>Proposta indisponível</h1><p class="sub">Este link expirou ou foi substituído por uma versão mais nova. Fale com a ATOM Digital pelo WhatsApp.</p>') };
  const t = String(token || '').trim();
  if (!/^[a-f0-9]{24,64}$/.test(t)) return nao;
  const p = (propostas || []).find((x) => x && x.token === t);
  if (!p) return nao;
  const maisNova = (propostas || []).some((x) => x && x.deal_id === p.deal_id && Number(x.versao) > Number(p.versao));
  if (maisNova || ['recusada', 'cancelada'].includes(p.status)) return nao;
  const e = (empresas || []).find((x) => x && x.company_id === p.company_id) || {};
  const vencida = String(p.validade_ate) < agora && p.status !== 'aceita';
  const aceita = p.status === 'aceita';
  const corpo = `<h1>Proposta · ${esc(e.nome || '')}</h1><p class="sub">${esc(p.proposal_id)} · ${esc(p.servico)} · ${aceita ? 'aceita em ' + dataBR(p.aceita_em) : vencida ? 'validade encerrada em ' + dataBR(p.validade_ate) : 'válida até ' + dataBR(p.validade_ate)}</p>
<section class="card"><h2>Escopo</h2><div class="escopo">${esc(p.escopo)}</div></section>
<section class="card"><h2>Investimento</h2><div class="valor">${brl(p.valor_total)}</div><p>Condições: ${esc(p.condicoes)}<br>Prazo: ${esc(p.prazo)}</p></section>
${aceita ? '<p class="card">Proposta aceita. Vamos confirmar o escopo e encaminhar o contrato pela Autentique.</p>' : vencida ? '<p class="card">A validade terminou. Responda no WhatsApp que atualizamos para você.</p>' : `<section class="card"><p>Ao aceitar, confirmamos o escopo e enviamos o contrato pela Autentique para assinatura. Nenhuma cobrança é feita antes do contrato assinado.</p><button id="ac">Aceitar proposta</button><span class="status" role="status"></span></section>`}
<p>${botaoWhats(cfg, 'Tenho uma dúvida sobre a proposta ' + p.proposal_id)}</p>
<footer>Proposta preparada pela ATOM Digital. Dúvidas? Responda a mensagem do WhatsApp.</footer>`;
  const js = aceita || vencida ? '' : `<script>const T=${JSON.stringify(t)};document.getElementById('ac').addEventListener('click',async(ev)=>{if(!confirm('Confirmar o aceite desta proposta?'))return;const b=ev.target,st=b.nextElementSibling;b.disabled=true;st.textContent='Registrando…';
try{const r=await fetch(location.pathname+'-aceite?t='+encodeURIComponent(T),{method:'POST'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.erro||'erro');st.textContent=j.mensagem;}catch(e){st.textContent='Não registrado: '+e.message;b.disabled=false;}});</script>`;
  return { status: 200, html: pagina('Proposta · ' + (e.nome || ''), corpo, js), proposta: { proposal_id: p.proposal_id, vistas: Number(p.vistas || 0) + 1 } };
}
const cfg = Object.fromEntries($('Ler config (ver)').all().map((i) => i.json).filter((r) => r && r.chave).map((r) => [r.chave, String(r.valor ?? '')]));
return [{ json: paginaProposta(($('Proposta (GET)').first().json.query || {}).t, $('Ler propostas (ver)').all().map((i) => i.json), $('Ler empresas (ver)').all().map((i) => i.json), new Date().toISOString(), cfg) }];

// ATOM2_W10 · Aceite da proposta (trecho de n8n/code/w10_proposta.js). Aceite pela página → proposta aceita, negócio GANHO (= aceite, F11).
const API = 'https://api.pipedrive.com/v1';
const cfgMapa = (rows) => Object.fromEntries((rows || []).filter((r) => r && r.chave).map((r) => [r.chave, String(r.valor ?? '')]));
// Aceite: só a versão mais nova, dentro da validade, ainda não aceita.
function aceitar(token, propostas, empresas, cfgRows, ip, agoraISO) {
  const cfg = cfgMapa(cfgRows);
  const agora = agoraISO || new Date().toISOString();
  const t = String(token || '').trim();
  const p = /^[a-f0-9]{24,64}$/.test(t) ? (propostas || []).find((x) => x && x.token === t) : null;
  if (!p) return { ok: false, erro: 'proposta não encontrada' };
  if ((propostas || []).some((x) => x && x.deal_id === p.deal_id && Number(x.versao) > Number(p.versao))) return { ok: false, erro: 'existe uma versão mais nova' };
  if (p.status === 'aceita') return { ok: true, mensagem: 'Proposta já aceita. Obrigado!', repetido: true };
  if (p.status !== 'enviada') return { ok: false, erro: 'proposta indisponível' };
  if (String(p.validade_ate) < agora) return { ok: false, erro: 'validade encerrada' };
  const e = (empresas || []).find((x) => x && x.company_id === p.company_id) || {};
  const teste = String(p.company_id).startsWith('c_teste_');
  return {
    ok: true, mensagem: 'Excelente! Vou confirmar o escopo e encaminhar o contrato pela Autentique, conforme combinado.',
    proposta: { proposal_id: p.proposal_id, status: 'aceita', aceita_em: agora, aceite_ip: String(ip || '').slice(0, 64) },
    empresa: { company_id: p.company_id, funil_etapa: 'F11', status_motivo: 'Ganho: proposta ' + p.proposal_id + ' aceita', atualizado_em: agora },
    pd: [
      { method: 'PUT', url: API + '/deals/' + p.deal_id, body: { status: 'won', ...(cfg.PD2_FIELD_PROXIMA_ACAO ? { [cfg.PD2_FIELD_PROXIMA_ACAO]: 'Formalizar: contrato (Autentique) e cobrança (Asaas)' } : {}) } },
      { method: 'POST', url: API + '/activities', body: { deal_id: Number(p.deal_id), subject: 'Proposta aceita: conferir dados e liberar o contrato', type: 'task', due_date: agora.slice(0, 10) } }
    ],
    evento: { event_id: 'e_w10_' + p.proposal_id + '_aceita', correlation_id: 'deal_' + p.deal_id, company_id: p.company_id, workflow: 'ATOM2_W10', tipo: 'PROPOSTA_ACEITA', motivo: teste ? 'registro de teste' : 'aceite pela página', dados: JSON.stringify({ valor_total: p.valor_total, nome: e.nome || '' }), ocorrido_em: agora }
  };
}
const h = $('Aceite (POST)').first().json;
const ip = String((h.headers || {})['x-forwarded-for'] || '').split(',')[0].trim();
return [{ json: aceitar((h.query || {}).t, $('Ler propostas (aceite)').all().map((i) => i.json), $('Ler empresas (aceite)').all().map((i) => i.json), $('Ler config (aceite)').all().map((i) => i.json), ip) }];

const a = $('Registrar aceite').first().json;
const r = $('Ganho no Pipedrive').all().map((i) => i.json);
const ok = r[0] && r[0].success === true;
const out = [{ destino: 'proposta', linha: a.proposta }, { destino: 'empresa', linha: a.empresa }, { destino: 'evento', linha: a.evento }];
if (!ok) out.push({ destino: 'evento', linha: { ...a.evento, event_id: a.evento.event_id + '_crm_falha', tipo: 'CRM_FALHA', motivo: 'Pipedrive recusou marcar ganho: marcar à mão', dados: JSON.stringify({ erro: (r[0] && (r[0].error || r[0].error_info)) || null }) } });
return out.map((j) => ({ json: j }));
